def make_article(a):
    """Render an article to a complete HTML file using the canonical template."""
    about = [k.strip() for k in a["kw"].split(",")]
    head = f"""<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>{a['title']}</title>
    <meta name="description" content="{a['desc']}">
    <meta name="keywords" content="{a['kw']}">
    <meta name="robots" content="index, follow">
    <link rel="canonical" href="https://ribbonbow123.com/{a['slug']}.html">
    <meta property="og:title" content="{a['title']}">
    <meta property="og:description" content="{a['desc']}">
    <meta property="og:type" content="article">
    <meta property="og:url" content="https://ribbonbow123.com/{a['slug']}.html">
    <meta property="og:image" content="https://ribbonbow123.com/img/banner.png">
    <meta property="og:site_name" content="Smith Ribbon">
    <meta property="og:locale" content="en_US">
    <meta property="article:published_time" content="{a['published']}">
    <meta property="article:section" content="{a['section']}">
    <meta property="article:author" content="Smith Ribbon OEM Editorial Team">
    <meta name="twitter:card" content="summary_large_image">
    <meta name="twitter:title" content="{a['title']}">
    <meta name="twitter:description" content="{a['desc']}">
    <link rel="stylesheet" href="/seo-header.html">
    <style>
    body {{ font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.7; color: #2c3e50; max-width: 880px; margin: 0 auto; padding: 24px; background: #fafbfc; }}
    .post-header {{ background: linear-gradient(135deg, #1a5f7a 0%, #159895 100%); color: white; padding: 32px; border-radius: 12px; margin-bottom: 32px; }}
    .post-header h1 {{ font-size: 28px; margin: 0 0 12px; line-height: 1.3; }}
    .post-meta {{ font-size: 14px; opacity: 0.9; }}
    .post-section {{ background: white; padding: 28px; border-radius: 8px; margin-bottom: 18px; box-shadow: 0 2px 8px rgba(0,0,0,0.04); }}
    .post-section h2 {{ color: #1a5f7a; font-size: 22px; margin: 0 0 14px; line-height: 1.4; }}
    .post-section p {{ font-size: 15px; color: #333; }}
    em {{ color: #159895; font-style: normal; font-weight: 600; }}
    </style>
    <script type="application/ld+json">
    {{
      "@context": "https://schema.org",
      "@type": "BlogPosting",
      "headline": "{a['title']}",
      "description": "{a['desc']}",
      "author": {{ "@type": "Organization", "name": "Xiamen Smith Ribbon & Bow Co., Ltd." }},
      "publisher": {{ "@type": "Organization", "name": "Smith Ribbon", "logo": {{ "@type": "ImageObject", "url": "https://ribbonbow123.com/img/banner.png" }} }},
      "datePublished": "{a['published']}",
      "dateModified": "{a['published']}",
      "image": "https://ribbonbow123.com/img/banner.png",
      "url": "https://ribbonbow123.com/{a['slug']}.html",
      "keywords": "{a['kw']}",
      "wordCount": {a['wordCount']},
      "timeRequired": "{a['timeRequired']}",
      "inLanguage": "en-US",
      "articleSection": "{a['section']}",
      "about": {about}
    }}
    </script>
</head>
<body>
    <article>
        <header class="post-header">
            <h1>{a['h1']}</h1>
            <div class="post-meta">August 26, 2026 &middot; 27 min read &middot; Smith Ribbon OEM Editorial Team</div>
        </header>
"""
    body_parts = []
    for h2, p in a["sections"]:
        body_parts.append(f"""
        <section class="post-section">
            <h2>{h2}</h2>
            <p>{p}</p>
        </section>""")
    tail = """
    </article>
</body>
</html>
"""
    return head + "".join(body_parts) + tail


def make_blog_entry(a):
    return (f'    <li><a href="{a["slug"]}.html">{a["title"]}</a><br><span '
            f'class="blog-desc">{a["desc"]}</span></li>')


def make_sitemap_entry(a):
    lastmod = a["published"][:10]
    return (f'  <url>\n'
            f'    <loc>https://ribbonbow123.com/{a["slug"]}.html</loc>\n'
            f'    <lastmod>{lastmod}</lastmod>\n'
            f'    <changefreq>monthly</changefreq>\n'
            f'    <priority>0.8</priority>\n'
            f'  </url>')


# Write Article 1
a1_path = os.path.join(BASE, A1["slug"] + ".html")
with open(a1_path, "w", encoding="utf-8") as f:
    f.write(make_article(A1))
print(f"WROTE: {a1_path} ({os.path.getsize(a1_path)} bytes)")

# Write Article 2
a2_path = os.path.join(BASE, A2["slug"] + ".html")
with open(a2_path, "w", encoding="utf-8") as f:
    f.write(make_article(A2))
print(f"WROTE: {a2_path} ({os.path.getsize(a2_path)} bytes)")

# Update blog.html — add to AM and PM sections
blog_path = os.path.join(BASE, "blog.html")
with open(blog_path, "r", encoding="utf-8") as f:
    blog = f.read()

am_marker = '<section><h2>Latest B2B Articles (2026-08-26 AM)</h2><ul>\n'
pm_marker = '<section><h2>Latest B2B Articles (2026-08-26 PM)</h2><ul>\n'

if am_marker in blog:
    blog = blog.replace(am_marker, am_marker + make_blog_entry(A1) + "\n", 1)
if pm_marker in blog:
    blog = blog.replace(pm_marker, pm_marker + make_blog_entry(A2) + "\n", 1)

with open(blog_path, "w", encoding="utf-8") as f:
    f.write(blog)
print(f"UPDATED: {blog_path}")

# Update sitemap.xml
sitemap_path = os.path.join(BASE, "sitemap.xml")
with open(sitemap_path, "r", encoding="utf-8") as f:
    sm = f.read()

# Insert new entries before </urlset>
entries = make_sitemap_entry(A1) + "\n" + make_sitemap_entry(A2) + "\n"
sm = sm.replace("</urlset>", entries + "</urlset>")

with open(sitemap_path, "w", encoding="utf-8") as f:
    f.write(sm)
print(f"UPDATED: {sitemap_path}")

print("DONE")
